package com.sim.backend.config; import com.mongodb.client.MongoClient; import com.mongodb.client.MongoClients; import de.bwaldvogel.mongo.MongoServer; import de.bwaldvogel.mongo.backend.memory.MemoryBackend; import org.springframework.context.annotation.Bean; import org.springframework.context.annotation.Configuration; import java.net.InetSocketAddress; @Configuration public class EmbeddedMongoConfig { @Bean(destroyMethod = "shutdown") public MongoServer mongoServer() { MongoServer server = new MongoServer(new MemoryBackend()); server.bind("localhost", 27017); return server; } @Bean public MongoClient mongoClient(MongoServer mongoServer) { InetSocketAddress addr = mongoServer.getLocalAddress(); return MongoClients.create("mongodb://" + addr.getHostString() + ":" + addr.getPort()); } }